create table integration_keys(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,name text not null,token_hash text not null unique,scopes text[] not null,connection_ids int[] not null default '{}',active boolean not null default true,created_at timestamptz not null default now(),last_used_at timestamptz);
create table integration_hooks(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,name text not null,url text not null,events text[] not null,secret text not null,active boolean not null default true,created_at timestamptz not null default now());
create table integration_outbox(id uuid primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,hook_id int not null references integration_hooks,event text not null,payload jsonb not null,status text not null default 'pending' check(status in ('pending','sending','delivered','failed')),attempts int not null default 0,due_at timestamptz not null default now(),last_error text,delivered_at timestamptz,created_at timestamptz not null default now());
create index integration_due on integration_outbox(due_at) where status in ('pending','sending');
do $$ declare t text;begin foreach t in array array['integration_keys','integration_hooks','integration_outbox'] loop
 execute format('alter table %I enable row level security',t);execute format('alter table %I force row level security',t);execute format($f$create policy tenant_iso on %I using(tenant_id=nullif(current_setting('app.tenant',true),'')::int) with check(tenant_id=nullif(current_setting('app.tenant',true),'')::int)$f$,t);end loop;end $$;
create trigger integration_hook_guard before insert or update on integration_outbox for each row execute function fk_guard('integration_hooks','hook_id');
